#!/usr/bin/env node
/**
 * Detect drift between bootstrap-generated artifacts and their sources.
 *
 * Bootstrap artifacts (root MEMORY.md, AGENTS.md, CLAUDE.md, GEMINI.md, .claude/,
 * .codex/, .trae/, .codebuddy/, .qoder/) are .gitignored and regenerated by
 * `npm run bootstrap`. If any of them has been touched more recently than its
 * source — or has been edited directly without a bootstrap re-run — this script
 * flags the drift. Catches the "Edit routes/MEMORY.md writes to root MEMORY.md"
 * class of bugs.
 *
 * Exit 0 = clean, 1 = drift found (printed as [FAIL]).
 */
import { existsSync, statSync } from "node:fs";
import { resolve, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..");

let fail = 0;

function ok(msg: string): void {
  console.log(`[ok]   ${msg}`);
}

function bad(msg: string): void {
  console.log(`[FAIL] ${msg}`);
  fail = 1;
}

function mtimeMs(p: string): number {
  try {
    return statSync(p).mtimeMs;
  } catch {
    return -1;
  }
}

function rel(p: string): string {
  return p.slice(ROOT.length + 1).replaceAll("\\", "/");
}

interface Pair {
  artifact: string; // bootstrap output (gitignored)
  source: string; // canonical source the artifact is generated from
  note?: string;
}

const PAIRS: Pair[] = [
  { artifact: "MEMORY.md", source: "routes/code/MEMORY.md", note: "code route (default)" },
  { artifact: "AGENTS.md", source: "platforms/codex/rules/ENTRY.md", note: "Codex native entry" },
  { artifact: "CLAUDE.md", source: "platforms/claude/rules/ENTRY.md", note: "Claude native entry" },
  { artifact: "GEMINI.md", source: "platforms/qoder/rules/ENTRY.md", note: "Gemini mirror (qoder-side)" },
  { artifact: ".claude/CLAUDE.md", source: "platforms/claude/rules/ENTRY.md" },
  { artifact: ".codex/AGENTS.md", source: "platforms/codex/rules/ENTRY.md" },
  { artifact: ".trae/rules/ENTRY.md", source: "platforms/trae/rules/ENTRY.md" },
  { artifact: ".codebuddy/AGENTS.md", source: "platforms/workbuddy/rules/ENTRY.md" },
  { artifact: ".qoder/AGENTS.md", source: "platforms/qoder/rules/ENTRY.md" },
];

for (const p of PAIRS) {
  const artPath = resolve(ROOT, p.artifact);
  const srcPath = resolve(ROOT, p.source);
  if (!existsSync(artPath)) {
    // Artifact absent: probably never bootstrapped. Not necessarily a failure.
    console.log(`[skip] ${p.artifact} (absent) — run \`npm run bootstrap\` to generate`);
    continue;
  }
  if (!existsSync(srcPath)) {
    bad(`${p.artifact}: source missing -> ${p.source}`);
    continue;
  }
  const aMtime = mtimeMs(artPath);
  const sMtime = mtimeMs(srcPath);
  if (sMtime > aMtime) {
    bad(
      `${p.artifact} is STALE: source ${p.source} (mtime ${sMtime.toFixed(0)}) is newer than artifact (mtime ${aMtime.toFixed(0)}); re-run \`npm run bootstrap\``,
    );
  } else {
    ok(`${p.artifact} <= ${p.source}${p.note ? ` (${p.note})` : ""}`);
  }
}

if (fail === 0) {
  console.log("");
  console.log("No bootstrap drift detected.");
} else {
  console.log("");
  console.log("Bootstrap drift found — re-run `npm run bootstrap` or revert the artifact.");
  process.exit(1);
}
